@startuml

class Organizer {
  + firstName : string
  + lastName : string
  + email : string
  + postalAddress : string
  + phoneNumber : string
  + password : string
}

class EventType {
  + name : string
}

class Location {
  + name : string
  + address : string
}

class Event {
  + occasion : string
  + startDateTime : datetime
  + endDateTime : datetime
}

class Attendee {
  + firstName : string
  + lastName : string
  + email : string
  + password : string
  + attendanceStatus : string
}

class Task {
  + description : string
  + status : string
}

class TaskAssignment {
  + isAccomplished : boolean
}

Organizer "1..*" -- "1" Event : organizes
Event "*" -- "1" EventType
Event "*" -- "1" Location
Event "1" *-- "0..*" Task
Event "1" -- "0..*" Attendee : invites

Organizer "0..1" -- "0..*" Event : attends

Attendee "0..*" -- "0..*" Task : selects
Task "1" -- "0..1" TaskAssignment : assigned to
TaskAssignment "*" -- "1" Attendee : performed by

@enduml

